<script setup lang="ts">
/**
 * The CityPal logo as a small rounded tile (docs/DESIGN.md "Brand"): a
 * heart-shaped padlock made of locker compartments around a green city,
 * with a cargo bike. The light version (white background) is shown in light
 * mode, the dark one (near-black background) when the device is in dark
 * mode, like the rest of the theme (`prefers-color-scheme`).
 *
 * Decorative: the product name always sits next to it as text, so it is
 * hidden from assistive technologies. The images are generated by
 * `scripts/build-brand-icons.cjs` from `packages/ui/brand/`.
 *
 * Props:
 * - `size`: width and height in CSS pixels (default 32).
 */
withDefaults(defineProps<{ size?: number }>(), { size: 32 });

// Resolved by Vite at build time (no type declaration needed for images).
const light = new URL("../brand/citypal-mark-light.png", import.meta.url).href;
const dark = new URL("../brand/citypal-mark-dark.png", import.meta.url).href;
</script>

<template>
  <picture class="brand-mark" aria-hidden="true">
    <source :srcset="dark" media="(prefers-color-scheme: dark)" />
    <img :src="light" :width="size" :height="size" alt="" />
  </picture>
</template>

<style scoped>
.brand-mark {
  display: block;
  flex: none;
}
.brand-mark img {
  display: block;
  border-radius: 22%;
}
</style>
